"use client";

import { useEffect, useMemo, useState } from "react";
import type { TemperatureUnit } from "./usePreferences";

export interface WeatherData {
  isDay: boolean;
  temperature: number; // Always in Celsius from API
  weatherCode: number;
}

interface OpenMeteoResponse {
  current: {
    temperature_2m: number;
    weather_code: number;
    is_day: 0 | 1;
  };
}

const TORONTO_COORDS = { lat: 43.6532, lng: -79.3832 };

function convertTemperature(celsius: number, unit: TemperatureUnit): number {
  switch (unit) {
    case "C":
      return celsius;
    case "F":
      return (celsius * 9) / 5 + 32;
    case "K":
      return celsius + 273.15;
    case "R":
      return ((celsius + 273.15) * 9) / 5;
    case "Re":
      return celsius * 0.8;
    case "De":
      return (100 - celsius) * 1.5;
    default:
      return celsius;
  }
}

export function useWeather(unit: TemperatureUnit = "C") {
  const [weather, setWeather] = useState<WeatherData | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    const fetchWeather = async () => {
      try {
        const res = await fetch(
          `https://api.open-meteo.com/v1/forecast?latitude=${TORONTO_COORDS.lat}&longitude=${TORONTO_COORDS.lng}&current=temperature_2m,weather_code,is_day`,
          { signal: controller.signal }
        );
        const data = (await res.json()) as OpenMeteoResponse;
        setWeather({
          temperature: data.current.temperature_2m,
          weatherCode: data.current.weather_code,
          isDay: data.current.is_day === 1,
        });
      } catch (e: unknown) {
        if (e instanceof Error && e.name === "AbortError") {
          return;
        }
        console.error("Failed to fetch weather", e);
      }
    };

    fetchWeather();
    // Refresh weather every 30 minutes
    const interval = setInterval(fetchWeather, 30 * 60 * 1000);
    return () => {
      controller.abort();
      clearInterval(interval);
    };
  }, []);

  const tempValue = useMemo(() => {
    if (!weather) {
      return null;
    }
    return Math.round(convertTemperature(weather.temperature, unit));
  }, [weather, unit]);

  return { weather, tempValue };
}

"use client";

import { useEffect, useState } from "react";
import { useMounted } from "./useMounted";

export type TemperatureUnit = "C" | "F" | "K" | "R" | "Re" | "De";

export function usePreferences() {
  const mounted = useMounted();

  const [tempUnit, setTempUnit] = useState<TemperatureUnit>(() => {
    if (typeof window === "undefined") {
      return "C";
    }
    try {
      const storedUnit = localStorage.getItem("pref-temp-unit");
      if (storedUnit && ["C", "F", "K", "R", "Re", "De"].includes(storedUnit)) {
        return storedUnit as TemperatureUnit;
      }
      // Fallback for migration
      const oldPref = localStorage.getItem("pref-fahrenheit");
      if (oldPref !== null) {
        return oldPref === "true" ? "F" : "C";
      }
    } catch (e) {
      console.error("Failed to load tempUnit preference", e);
    }
    return "C";
  });

  const [use24Hour, setUse24Hour] = useState(() => {
    if (typeof window === "undefined") {
      return false;
    }
    try {
      const stored = localStorage.getItem("pref-24h");
      return stored === "true";
    } catch (e) {
      console.error("Failed to load use24Hour preference", e);
      return false;
    }
  });

  const [showCoords, setShowCoords] = useState(() => {
    if (typeof window === "undefined") {
      return false;
    }
    try {
      const stored = localStorage.getItem("pref-show-coords");
      return stored === "true";
    } catch (e) {
      console.error("Failed to load showCoords preference", e);
      return false;
    }
  });

  // Cycle through units: C -> F -> K -> R -> Re -> De -> C
  const toggleUnit = () => {
    setTempUnit((prev) => {
      const map: Record<TemperatureUnit, TemperatureUnit> = {
        C: "F",
        F: "K",
        K: "R",
        R: "Re",
        Re: "De",
        De: "C",
      };
      return map[prev];
    });
  };

  const tempUnitLabel = (() => {
    switch (tempUnit) {
      case "C":
        return "°C";
      case "F":
        return "°F";
      case "K":
        return "K";
      case "R":
        return "°R";
      case "Re":
        return "°Re";
      case "De":
        return "°De";
      default:
        return "°C";
    }
  })();

  // Save preferences
  useEffect(() => {
    if (!mounted) {
      return;
    }
    localStorage.setItem("pref-24h", String(use24Hour));
    localStorage.setItem("pref-temp-unit", tempUnit);
    localStorage.setItem("pref-show-coords", String(showCoords));
  }, [use24Hour, tempUnit, showCoords, mounted]);

  return {
    tempUnit,
    setTempUnit,
    toggleUnit,
    tempUnitLabel,
    use24Hour,
    setUse24Hour,
    showCoords,
    setShowCoords,
    mounted,
  };
}

"use client";

import { useEffect, useState } from "react";

export function useMounted() {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  return mounted;
}
